<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {send} from '../api';const router=useRouter(),email=ref(''),password=ref(''),error=ref(''),busy=ref(false);async function login(){busy.value=true;error.value='';try{await send('/auth/login',{email:email.value,password:password.value});router.replace('/admin')}catch(e){error.value=e.message}finally{busy.value=false}}</script>
<template><div class="login-screen"><div class="login-left"><router-link to="/" class="login-logo">◈ 约客助手</router-link><div><div class="eyebrow">FOR THE MOMENTS THAT MATTER</div><h1>更专注创作，<br/><em>让预约井井有条。</em></h1><p>让工作室的每一份预约都有迹可循。</p></div><div class="login-footer">APPOINTMENT ASSISTANT · STUDIO EDITION</div></div><main class="login-right"><form class="login-form" @submit.prevent="login"><div class="eyebrow dark">WELCOME BACK</div><h2>登录工作台</h2><p class="muted">使用工作室管理员账号继续</p><label>登录邮箱<input v-model="email" type="email" autocomplete="username" placeholder="name@example.com" required/></label><label>登录密码<input v-model="password" type="password" autocomplete="current-password" placeholder="输入你的密码" required/></label><div v-if="error" class="alert">{{error}}</div><button class="button primary big" :disabled="busy">{{busy?'正在验证…':'进入工作台'}} ↗</button><div class="login-help">账号由平台管理员初始化。不支持公开注册。</div></form></main></div></template>
